<template><div class="spotlight-home min-h-screen bg-[#f4f1ea] text-stone-900"><section class="mx-auto grid max-w-6xl gap-8 px-4 py-10 md:grid-cols-[1.2fr_.8fr] md:py-20"><div class="flex flex-col justify-center"><p class="text-sm font-bold uppercase tracking-[.3em] text-violet-700">{{ t('home.featured.title') }}</p><h1 class="mt-4 text-5xl font-black leading-none md:text-7xl">{{ featured ? getLocalizedText(featured.title) : t('home.featured.description') }}</h1><p class="mt-6 max-w-md text-lg text-stone-600">{{ featured ? getLocalizedText(featured.description) : t('home.latest.description') }}</p><RouterLink v-if="featured" :to="`/products/${featured.slug}`" class="mt-8 inline-flex h-12 w-fit items-center rounded-full bg-stone-900 px-7 text-sm font-bold text-white">{{ t('home.featured.viewAll') }}</RouterLink></div><div class="relative aspect-[4/5] overflow-hidden rounded-[2rem] bg-stone-300"><img v-if="featured?.cover" :src="featured.cover" :alt="getLocalizedText(featured.title)" class="h-full w-full object-cover"/><div v-else class="grid h-full place-items-center text-stone-500">{{ t('home.featured.empty') }}</div><span class="absolute left-5 top-5 rounded-full bg-white/85 px-3 py-1 text-xs font-bold">01</span></div></section><section class="mx-auto max-w-6xl px-4 pb-16"><div class="mb-5 flex items-center justify-between"><h2 class="text-2xl font-black">{{ t('home.latest.title') }}</h2><RouterLink to="/products" class="text-sm font-bold text-violet-700">{{ t('home.featured.viewAll') }}</RouterLink></div><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><ProductCard v-for="(p,i) in products.slice(1)" :key="p.id" :product="p" :index="i" @click="go(p.slug)" @quick-buy="quickBuy" /></div></section><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></div></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { productAPI } from '../../api'; import { useLocalized } from '../../composables/useProduct'; import ProductCard from '../../components/ProductCard.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; const {t}=useI18n(); const {getLocalizedText}=useLocalized(); const router=useRouter(); const products=ref<any[]>([]); const selected=ref<any>(null); const quickVisible=ref(false); const featured=computed(()=>products.value[0]); const go=(s:string)=>router.push(`/products/${s}`); const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true}; onMounted(async()=>{const r=await productAPI.list({page:1,page_size:9});products.value=r.data.data||[]})</script>
